class ConectorTikTokMock(ConectorBase):
    """
    ══════════════════════════════════════════════════════════
    CONECTOR TIKTOK — MODO MOCK
    ══════════════════════════════════════════════════════════
    API REAL: TikTok Research API
      https://developers.tiktok.com/

    1. Solicita acceso: cuenta de desarrollador verificada
    2. Agrega al .env:
         TIKTOK_CLIENT_KEY=...
         TIKTOK_CLIENT_SECRET=...
    3. Auth: POST https://open.tiktokapis.com/v2/oauth/token/
    4. Query: POST https://open.tiktokapis.com/v2/video/query/
       Body: {"query":{"and":[{"field_name":"hashtag_name","field_values":[...tags]}]}}
    ══════════════════════════════════════════════════════════
    """
    nombre = "TikTok"

    def extraer_raw(self, tags: list[str]) -> list[dict]:
        """Retorna datos en formato nativo TikTok (crudos, sin transformar)."""
        if not tags:
            return POSTS_RAW
        q = [t.lower() for t in tags]
        return [
            p for p in POSTS_RAW
            if any(
                t in p["caption"].lower() or
                any(t in h.lower() for h in p["hashtags"]) or
                t in (p.get("location") or "").lower()
                for t in q
            )
        ]

    def extraer(self, tags: list[str]) -> list[dict]:
        """Compatibilidad con el pipeline antiguo — delega a extraer_raw."""
        return self.extraer_raw(tags)
